properties.query:
// Only events ingested since the last run (see tools/build.py)
let CowrieNew = Cowrie_CL | where ingestion_time() > ago(1h);
CowrieNew
| where eventid =~ "cowrie.command.input" and (input matches regex "chmod\\s+(-[a-zA-Z]+\\s+)?([ugoa]*\\+[rw]*x|[0-7]*[1357][0-7]*)\\s+\\S+\\s*(;|&&)\\s*((ba)?sh\\s+)?(\\./|/)\\S+" or input matches regex "\\bchattr\\s+-[a-zA-Z]*[ia]") and (not(input matches regex "\\b(wget|curl|tftp|ftpget)\\b"))
// One alert per source IP
| summarize Matches = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by src_ip
